  "interview": [
    {
      "id": "interview-01",
      "articleIds": [
        "2026-10-17-top-1"
      ],
      "question": "量子化したローカルモデルを選ぶとき、容量と性能をどう評価しますか。",
      "answer": "重みの容量だけでなく、実行時のメモリと課題の成績を分けて見ます。BoltはexpertをIQ2_XXSにし、DFlashで単発の生成を速めています。ただし、実測の常駐は約31GiBで、24GBという設計目標とは条件が違います。並列時の速度や、要約で答えが出なかった例も含め、使う仕事に合うか判断します。"
    },
    {
      "id": "interview-02",
      "articleIds": [
        "2026-10-17-top-2"
      ],
      "question": "CIで使うアクションの依存を、どう再現可能な状態に保ちますか。",
      "answer": "ワークフローだけでなく、内側の依存も固定して変更をレビューします。actions.lockは推移的依存のcommitやリポジトリIDを記録し、未登録の追加はstartup_failureで止まります。タグが動いても固定先は変わらず、更新はrelockで明示します。ただしpublic previewなので、生成時のワークフロー変更や許可リストへの影響も確認します。"
    },
    {
      "id": "interview-03",
      "articleIds": [
        "2026-10-17-top-3"
      ],
      "question": "開発環境で再現しない画面の不具合を、どう調べますか。",
      "answer": "まず機種、画面幅、押した後の変化を聞き、配信されたCSSを調べます。この例ではicon-btnが後ろにあり、同じ詳細度の非表示指定を上書きしていました。親のapp-barを加えて詳細度を上げ、本番ビルドの1400pxと375pxで計算済みスタイルを確認しています。ただし一つの構成の事例なので、実際の競合規則を見て修正を選びます。"
    },
    {
      "id": "interview-04",
      "articleIds": [
        "2026-10-17-top-4"
      ],
      "question": "エージェントの作業メモを外部へ保存するとき、何を確認しますか。",
      "answer": "保存して別セッションから読めることと、権限の分離を両方確かめます。ti fsではclaude配下へ読み書きできる24時間のトークンを使い、ルート一覧は拒否されました。ただし同じMacには広い権限の設定も残っていました。限定トークンだけで安全とせず、APIキーやオーナー設定のない実行環境へ分ける必要があります。"
    },
    {
      "id": "interview-05",
      "articleIds": [
        "2026-10-17-top-5"
      ],
      "question": "問い合わせ対応をAIへ任せるとき、何を成果として測りますか。",
      "answer": "回答を返した件数と、問題が解決した件数を分けます。SmartHRのDESKはSlackから過去記録やヘルプを調べ、現時点で約1割の問い合わせを解決しています。ただし、50%の自動クローズは今後の目標で、現状の解決率ではありません。提出処理の成功に加え、提出ボタンにたどり着けなかった利用者も見るのがCustomer Observabilityの構想です。"
    }
  ],
  "review": [
    {
      "id": "review-01",
      "articleIds": [
        "2026-10-17-top-1"
      ],
      "question": "量子化モデルの24GBという表記は、何と分けて読みますか。",
